# owner: platform
"""Plain text absence notices for parents."""

from typing import Iterable, List

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed


def _check_owner(student: Student, marks: List[Mark]) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark for student {mark.student_id!r} given for {student.student_id!r}"
            )


def _format_day(day) -> str:
    return f"{day:%A}, {day:%B} {day.day}, {day.year}"


def _compose(student: Student, missed: list) -> str:
    count = len(missed)
    unit = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    lines = [f"- {_format_day(day)}" for day in missed]
    head = f"{name} missed {count} {unit} of school:"
    return "\n".join([head] + lines)


# ---
def build_absence_notice(student: Student, marks: Iterable[Mark]) -> str:
    """Notice naming the student, days missed and the dates, oldest first."""
    items = list(marks)
    _check_owner(student, items)
    missed = sorted(set(days_missed(items)))
    if not missed:
        raise ValueError(f"no absences to report for {student.student_id!r}")
    return _compose(student, missed)
